<script module lang="ts">
/**
 * Bar showing how much of a task is done (`design/components/progress.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/progress.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/progress.module.css'

export type ProgressTone = NonNullable<ProgressProps['tone']>

export type ProgressShape = NonNullable<ProgressProps['shape']>

export interface ProgressProps {
  /**
   * Required, because an unnamed progress bar tells a screen reader nothing.
   */
  label: string
  /**
   * A bar as wide as its container, or a ring at an icon's size.
   */
  shape?: 'bar' | 'ring'
  /**
   * The ring's size, Spinner's sizes. A bar takes the width of its container and no size.
   */
  size?: 'sm' | 'md' | 'lg'
  /**
   * `danger` is for a task that failed or ran past its budget, not for "nearly done".
   */
  tone?: 'accent' | 'danger'
  /**
   * 0–100, clamped, because a bar cannot show more than full or less than empty.
   */
  value: number
}
</script>

<script lang="ts">
let {
  label: labelOwn,
  shape = 'bar',
  size = 'md',
  tone = 'accent',
  value,
}: ProgressProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn, size: size }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const percent = $derived(Math.min(100, Math.max(0, value)))
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if shape === 'ring'
    }<div
      class={styles.ring}
      data-shape="ring"
      data-size={size}
      data-tone={tone}
      role="progressbar"
      aria-label={label}
      aria-valuenow={percent}
      aria-valuemin={0}
      aria-valuemax={100}
      data-member="progress"
      ><svg class={styles.dial} aria-hidden="true" focusable="false"
        ><circle class={styles.groove} cx="50%" cy="50%" r="50%"></circle
        ><circle
          class={styles.arc}
          style:stroke-dashoffset={`${100 - percent}`}
          cx="50%"
          cy="50%"
          r="50%"
          pathLength={100}
        ></circle
      ></svg
    ></div
  >{:else
    }<div
      class={styles.track}
      data-tone={tone}
      role="progressbar"
      aria-label={label}
      aria-valuenow={percent}
      aria-valuemin={0}
      aria-valuemax={100}
      data-member="progress"
      ><div class={styles.fill} style:transform={`scaleX(${percent / 100})`}></div
    ></div
  >{/if
}{/if
}{@render joined.end?.()}
